// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes32 role, address account, address grantAdmin) public {
        vm.assume(role != bytes32(0));
        vm.assume(account != address(0));
        vm.assume(grantAdmin != address(0));
        vm.assume(!c.hasRole(role, account));

        bytes32 adminRole = c.getRoleAdmin(role);
        vm.assume(adminRole != bytes32(0));

        c.grantRole(adminRole, grantAdmin);

        vm.prank(grantAdmin);
        c.grantRole(role, account);

        assertTrue(c.hasRole(role, account));
    }
}
